@st.cache_data(show_spinner=False)
def get_sites():
    return load_sites()


@st.cache_resource(show_spinner="Preparing the sky lookup. This happens once.")
def get_lookup():
    return planner.build_lookup(START, END, max_window_days=MAX_DAYS)


@st.cache_data(show_spinner=False, max_entries=128)
def get_ranking(landing, days, limits):
    return planner.rank_for_date(
        get_lookup(), landing, window_days=days,
        min_sun_long_term=limits[0], min_earth_long_term=limits[1],
        min_sun_window=limits[2], min_earth_window=limits[3],
    )


@st.cache_data(show_spinner=False, max_entries=32)
def get_curve(site, landing, days):
    return planner.timeline(get_lookup(), site, landing, days)


@st.cache_data(show_spinner=False, max_entries=32)
def get_skyline(site):
    return planner.skyline(get_lookup(), site)


@st.cache_data(show_spinner=False, max_entries=4)
def get_scan(days):
    return planner.date_scan(get_lookup(), window_days=days)


def init_state():
    for key, value in {
        "step": 1, "landing_date": dt.date(2028, 1, 1), "landing_time": dt.time(0),
        "window_days": 14, "selected_site": None, "limits": (50, 50, 95, 95),
    }.items():
        st.session_state.setdefault(key, value)


def landing_datetime():
    # The planner accepts a naive datetime interpreted as UTC.
    return dt.datetime.combine(st.session_state.landing_date, st.session_state.landing_time)


def accept_mission():
    if not isinstance(st.session_state.input_landing_date, dt.date) or not isinstance(st.session_state.input_landing_time, dt.time):
        st.session_state.mission_error = "Choose a landing date and time before continuing."
        return
    st.session_state.pop("mission_error", None)
    for field in ("landing_date", "landing_time", "window_days"):
        st.session_state[field] = st.session_state["input_" + field]
    st.session_state.step = 2


def change_date():
    st.session_state.step = 1


def move_date():
    st.session_state.landing_date = st.session_state.explore_date


def select_site():
    st.session_state.selected_site = st.session_state.site_choice


def select_map_site():
    points = st.session_state.get("site_map", {}).get("selection", {}).get("points", [])
    if points:
        data = points[-1].get("customdata", [])
        if data and data[0] in set(get_sites()["site"]):
            st.session_state.selected_site = data[0]
            st.session_state.site_choice = data[0]


def shell():
    st.markdown(STYLE, unsafe_allow_html=True)
    st.markdown(
        '<div class="masthead"><div class="wordmark">LUNAR / LANDING</div>'
        '<div class="project-tag">Lunar Landing Optimal System<br>NASA Space Apps Challenge 2026 project</div></div>',
        unsafe_allow_html=True,
    )
    active = st.session_state.step
    st.markdown(
        '<div class="steps">'
        f'<span class="{"active" if active == 1 else ""}">01 &nbsp; Plan your mission</span>'
        f'<span class="{"active" if active == 2 else ""}">02 &nbsp; Explore landing sites</span></div>',
        unsafe_allow_html=True,
    )


def date_page():
    left, right = st.columns([1.5, 1], gap="large")
    with left:
        st.markdown('<div class="eyebrow">Lunar south pole / mission planning</div>', unsafe_allow_html=True)
        st.markdown('<div class="hero"><h1>A place to land.<br>A time to arrive.</h1></div>', unsafe_allow_html=True)
        st.markdown('<p class="hero-copy">Explore the balance between sunlight and a link to Earth. '
                    'Start with your arrival, then compare candidate landing sites.</p>', unsafe_allow_html=True)
        for field in ("landing_date", "landing_time", "window_days"):
            st.session_state.setdefault("input_" + field, st.session_state[field])
        with st.form("mission"):
            st.subheader("Plan your arrival")
            if st.session_state.get("mission_error"):
                st.error(st.session_state.mission_error)
            a, b = st.columns(2)
            a.date_input("Landing date (UTC)", min_value=START, max_value=END, key="input_landing_date")
            b.time_input("Landing time (UTC)", step=dt.timedelta(hours=1), key="input_landing_time")
            st.slider("Mission length (days)", 1, MAX_DAYS, key="input_window_days")
            st.caption("Hourly model: times are rounded to the nearest hour. Landing dates: 2027–2030.")
            st.form_submit_button("Explore landing sites →", type="primary", use_container_width=True,
                                  on_click=accept_mission)
    with right:
        st.markdown(
            '<div class="editorial"><div class="eyebrow">Your mission, in context</div>'
            '<h3>Sunlight. Contact. Timing.</h3>'
            '<p><strong>01 / Set the window</strong><br>Choose your arrival and how long the lander will operate.</p>'
            '<p><strong>02 / Compare the sites</strong><br>Inspect the polar map and the limits each candidate passes.</p>'
            '<p><strong>03 / Look to the horizon</strong><br>Follow the Sun and Earth against the real terrain skyline.</p></div>',
            unsafe_allow_html=True,
        )
        st.markdown(f"**{len(get_sites())} candidate regions** · NASA LOLA terrain and visibility data")
        st.info(ESTIMATE + " Site-specific calibration matches NASA's long-term visibility figures. "
                "Conditions on an individual date remain estimates.")
        st.caption("Earth visible means part of its disc is above the calibrated skyline. "
                   "A particular ground station may still be out of view.")


def chart_layout(fig, height=330):
    fig.update_layout(height=height, margin=dict(l=15, r=15, t=35, b=15),
                      paper_bgcolor=PANEL, plot_bgcolor=PANEL, font=dict(color="#bdcadd"),
                      legend=dict(orientation="h", y=1.2), hoverlabel=dict(bgcolor="#233349"),
                      xaxis=dict(gridcolor="#26364b", automargin=True),
                      yaxis=dict(gridcolor="#26364b", automargin=True))
    return fig


def make_map(ranked, selected):
    # No projection calculation. Every point uses the supplied x_km/y_km.
    rows = list(ranked.itertuples())
    fig = go.Figure(go.Scatter(
        x=ranked["x_km"].tolist(), y=ranked["y_km"].tolist(), mode="markers+text",
        text=[str(r.rank) for r in rows], textposition="middle center",
        textfont=dict(color="#101b2a", size=11),
        customdata=[[r.site, r.sun_window, r.earth_window,
                     "Passes limits" if r.passes else r.fail_reasons] for r in rows],
        marker=dict(size=[28 if r.site == selected else 23 for r in rows],
                    color=[GREEN if r.passes else GREY for r in rows],
                    line=dict(color=[AMBER if r.site == selected else "#c4d0df" for r in rows],
                              width=[3 if r.site == selected else 1 for r in rows])),
        selected=dict(marker=dict(opacity=1)), unselected=dict(marker=dict(opacity=1)),
        hovertemplate="<b>%{customdata[0]}</b><br>Estimate anchored to NASA long-term data."
                      "<br>Window sunlight: %{customdata[1]:.1%}<br>Window Earth contact: %{customdata[2]:.1%}"
                      "<br>%{customdata[3]}<extra></extra>", showlegend=False,
    ))
    # Drawing bounds and rings are projected kilometre guides, not latitude or terrain.
    extent = max(190, float(ranked[["x_km", "y_km"]].abs().max().max()) + 25)
    for radius in (50, 100, 150):
        fig.add_shape(type="circle", x0=-radius, y0=-radius, x1=radius, y1=radius,
                      line=dict(color="#2b3d54", width=1), layer="below")
    fig.add_hline(y=0, line_color="#35455a", line_width=1, layer="below")
    fig.add_vline(x=0, line_color="#35455a", line_width=1, layer="below")
    for x, y, label in [(0, .96, "0° longitude"), (.96, 0, "90°E"), (-.96, 0, "90°W"),
                        (0, -.96, "180°"), (0, 0, "South pole")]:
        fig.add_annotation(x=x*extent, y=y*extent, text=label, showarrow=False,
                           font=dict(color="#a5b5c9", size=10), yshift=-13 if label == "South pole" else 0)
    chart_layout(fig, 530)
    fig.update_layout(margin=dict(l=12, r=12, t=12, b=12),
                      xaxis=dict(range=[-extent, extent], visible=False, constrain="domain"),
                      yaxis=dict(range=[-extent, extent], visible=False, scaleanchor="x", scaleratio=1, constrain="domain"),
                      dragmode="pan", clickmode="event+select", uirevision="south-pole-map")
    return fig


def number(value, unit="", digits=1):
    if value is None or not math.isfinite(float(value)):
        return "not available yet"
    return f"{value:.{digits}f}{unit}"


def setting_time(value):
    if value is None or not math.isfinite(float(value)):
        return "Beyond coverage"
    return "Already hidden" if value == 0 else f"{value:.0f} h"


def site_details(row):
    st.markdown('<div class="eyebrow">Selected candidate</div>', unsafe_allow_html=True)
    st.subheader(row.site)
    st.caption(f"{abs(row.lat):.3f}°{'S' if row.lat < 0 else 'N'} · "
               f"{abs(row.lon):.3f}°{'W' if row.lon < 0 else 'E'} · List position {row.rank}")
    if row.passes:
        st.success("Passes all selected limits")
    else:
        st.warning("Does not pass the selected limits\n\n" + row.fail_reasons)
    st.markdown("**Mission window**")
    st.caption(ESTIMATE)
    a, b = st.columns(2)
    a.metric("Window sunlight", f"{row.sun_window:.1%}")
    b.metric("Window Earth contact", f"{row.earth_window:.1%}")
    st.caption(f"Provisional score: {row.score:.3f} / 1. Equal average of the two window ratios "
               "and two long-term ratios; includes date-specific estimates.")
    st.markdown("**Long-term visibility · NASA LOLA**")
    a, b = st.columns(2)
    a.metric("Long-term sunlight", f"{row.sun_long_term:.1%}")
    b.metric("Long-term Earth visibility", f"{row.earth_long_term:.1%}")
    st.caption("18.6-year averages at this representative point, including terrain.")


def conditions_panel(row):
    st.subheader("At arrival & through the mission")
    st.caption(ESTIMATE + " Hourly samples. Elevations refer to disc centres; "
               "margin is the top edge above the calibrated visibility limit.")
    a, b, c, d = st.columns(4)
    a.metric("Sun elevation at arrival", number(row.sun_el_at_landing, "°"))
    b.metric("Earth elevation at arrival", number(row.earth_el_at_landing, "°"))
    c.metric("Time until sunset", setting_time(row.hours_to_sunset))
    d.metric("Time until Earthset", setting_time(row.hours_to_earthset))
    with st.expander("Visibility margins, directions & interruptions"):
        a, b = st.columns(2)
        a.write(f"**Sun margin:** {number(row.sun_margin_at_landing, '°')}  \n"
                f"**Sun direction:** {number(row.sun_az_at_landing, '°')}  \n"
                f"**Sun at arrival:** {'Visible' if row.sun_up_at_landing else 'Hidden'}  \n"
                f"**Longest darkness:** {number(row.longest_dark_h, ' h')}  \n"
                f"**Highest Sun elevation:** {number(row.max_sun_el_window, '°')}")
        b.write(f"**Earth margin:** {number(row.earth_margin_at_landing, '°')}  \n"
                f"**Earth direction:** {number(row.earth_az_at_landing, '°')}  \n"
                f"**Earth at arrival:** {'Visible' if row.earth_up_at_landing else 'Hidden'}  \n"
                f"**Longest communication blackout:** {number(row.longest_blackout_h, ' h')}")
        st.caption(ESTIMATE + " Negative margins mean hidden. Directions are clockwise from lunar north. "
                   "No setting found within lookup coverage does not imply permanent visibility.")


def panorama_chart(sky, curve, row):
    fig = go.Figure()
    az = sky["azimuth_deg"].tolist() + [360]
    terrain = sky["terrain_el_deg"].tolist() + [float(sky["terrain_el_deg"].iloc[0])]
    # The lower fill edge is only a chart boundary, not another terrain measurement.
    floor = min(-5.0, min(terrain) - 2)
    fig.add_trace(go.Scatter(x=az, y=[floor]*len(az), mode="lines",
                            line=dict(width=0), showlegend=False, hoverinfo="skip"))
    fig.add_trace(go.Scatter(x=az, y=terrain, mode="lines", name="LOLA terrain",
                            fill="tonexty", fillcolor="#344152", line=dict(color="#8594a8", width=1.5),
                            hovertemplate="Azimuth %{x:.0f}°<br>Terrain %{y:.2f}°<extra>LOLA skyline</extra>"))
    for body, label, color in [("sun", "Sun", AMBER), ("earth", "Earth", BLUE)]:
        limits = sky[body + "_limit_deg"].tolist()
        fig.add_trace(go.Scatter(x=az, y=limits + [limits[0]], mode="lines",
                                name=label + " visibility limit", line=dict(color=color, width=1, dash="dot")))
        # Hourly markers avoid connecting across the 359°/0° azimuth seam.
        fig.add_trace(go.Scatter(x=curve[body + "_az"], y=curve[body + "_el"], mode="markers",
                                name=label + " hourly centres", marker=dict(color=color, size=3, opacity=.5),
                                customdata=curve[[body + "_margin"]].values,
                                hovertemplate="Direction %{x:.1f}°<br>Centre elevation %{y:.2f}°"
                                              "<br>Top-edge margin %{customdata[0]:.2f}°<extra>" + label + "</extra>"))
        fig.add_trace(go.Scatter(x=[getattr(row, body + "_az_at_landing")],
                                y=[getattr(row, body + "_el_at_landing")], mode="markers",
                                name=label + " at arrival", marker=dict(color=color, size=11, line=dict(color="white", width=1)),
                                hovertemplate="Arrival centre: %{x:.1f}°, %{y:.2f}°<extra>" + label + "</extra>"))
    chart_layout(fig, 360)
    fig.update_layout(xaxis=dict(range=[0, 360], title="Azimuth clockwise from lunar north (degrees)",
                                tickvals=[0, 90, 180, 270, 360], ticktext=["N · 0°", "E · 90°", "S · 180°", "W · 270°", "N · 360°"]),
                      yaxis_title="Elevation (degrees)", legend=dict(font_size=10, y=1.3),
                      uirevision=row.site)
    return fig


def sky_panel(row, landing, days):
    st.subheader("Look to the horizon")
    st.caption(ESTIMATE)
    view = st.radio("Sky view", ["Terrain panorama", "Elevation over time", "Visibility margin over time"],
                    horizontal=True, label_visibility="collapsed")
    curve = get_curve(row.site, landing, days)
    if view == "Terrain panorama":
        fig = panorama_chart(get_skyline(row.site), curve, row)
        st.caption("Measured terrain with calibrated Sun/Earth limit lines. Dots trace hourly disc centres; "
                   "large markers show arrival. Marker sizes are symbolic. Visibility depends on the disc's "
                   "top-edge margin, not where its centre meets the raw terrain.")
    else:
        margin = view == "Visibility margin over time"
        fig = go.Figure()
        for body, label, color in [("sun", "Sun", AMBER), ("earth", "Earth", BLUE)]:
            field = body + ("_margin" if margin else "_el")
            fig.add_trace(go.Scatter(x=curve["time_utc"], y=curve[field], mode="lines", name=label,
                                    line=dict(color=color, width=2),
                                    hovertemplate="%{x|%d %b %Y %H:%M} UTC<br>%{y:.2f}°<extra>" + label + "</extra>"))
        fig.add_hline(y=0, line_dash="dot", line_color="#9aabc0",
                      annotation_text="Visibility threshold" if margin else "Level horizon")
        chart_layout(fig)
        fig.update_layout(hovermode="x unified", xaxis_title="Time (UTC)",
                          yaxis_title="Top-edge margin (degrees)" if margin else "Centre elevation (degrees)")
        st.caption("Positive margin means part of the disc clears its calibrated visibility limit."
                   if margin else "Elevation alone does not determine visibility. Use the margin view to account for terrain and calibration.")
    st.plotly_chart(fig, use_container_width=True, theme=None, key="sky_chart",
                    config={"displayModeBar": False, "scrollZoom": False})


def scan_panel(days):
    st.subheader("Explore other landing dates")
    st.caption(ESTIMATE + " Site × date visibility; loaded only when requested.")
    if not st.checkbox("Show date comparison", key="show_scan"):
        return
    a, b = st.columns(2)
    year = a.selectbox("Comparison year", list(range(START.year, END.year + 1)),
                       index=st.session_state.landing_date.year - START.year, key="scan_year")
    metric = b.radio("Window visibility", ["Sunlight", "Earth contact"], horizontal=True)
    with st.spinner("Preparing date comparison…"):
        scan = get_scan(days)
    # Reshape existing values only. Midnight-date scan is not a score or pass/fail map.
    subset = scan.loc[(scan["date"] >= dt.date(year, 1, 1)) & (scan["date"] <= dt.date(year, 12, 31))]
    table = subset.pivot(index="site", columns="date", values="sun_window" if metric == "Sunlight" else "earth_window")
    fig = go.Figure(go.Heatmap(x=table.columns.tolist(), y=table.index.tolist(), z=table.values,
                              zmin=0, zmax=1, colorscale=[[0, "#18283f"], [.5, "#447d88"], [1, "#f0cd91"]],
                              colorbar=dict(title="Visibility", tickformat=".0%", thickness=12),
                              hovertemplate="%{y}<br>%{x|%d %b %Y} · 00:00 UTC<br>" + metric +
                                            ": %{z:.1%}<extra>NASA-anchored estimate</extra>"))
    chart_layout(fig, 450)
    fig.update_layout(margin=dict(l=5, r=5, t=10, b=10), xaxis_title="Landing date (00:00 UTC)")
    st.plotly_chart(fig, use_container_width=True, theme=None, key="date_heatmap",
                    config={"displayModeBar": False, "scrollZoom": False})
    st.caption(f"Each cell uses a {days}-day mission starting at 00:00 UTC, regardless of the selected arrival time. "
               "Visibility only: this is not a score or pass/fail map.")


def sites_page():
    title, action = st.columns([4, 1])
    title.header("Find your place on the Moon.")
    action.button("← Edit mission", on_click=change_date, use_container_width=True)
    st.session_state.explore_date = st.session_state.landing_date
    st.slider("Explore landing date (UTC)", START, END, key="explore_date",
              format="DD MMM YYYY", on_change=move_date)
    landing, days = landing_datetime(), st.session_state.window_days
    st.markdown(f'<div class="mission-strip"><strong>{landing:%d %b %Y}</strong> &nbsp; / &nbsp; '
                f'{landing:%H:%M} UTC &nbsp; / &nbsp; {days} days on the surface</div>', unsafe_allow_html=True)
    st.caption(ESTIMATE + " Hourly samples; arrival time is rounded to the nearest hour.")
    with st.expander("Mission limits"):
        st.caption("The planner applies all four limits. Failed candidates remain visible.")
        values = []
        labels = ["Long-term sunlight", "Long-term Earth visibility", "Window sunlight", "Window Earth contact"]
        for i, (col, label, default) in enumerate(zip(st.columns(4), labels, st.session_state.limits)):
            values.append(col.slider(label, 0, 100, int(default), step=5, format="%d%%", key=f"limit_{i}"))
        st.session_state.limits = tuple(values)
    # Convert display percentages to the fractions expected by the planner.
    try:
        ranked = get_ranking(landing, days, tuple(v / 100 for v in st.session_state.limits))
    except (ValueError, OSError) as exc:
        st.error(f"Unable to load this mission: {exc}")
        return
    if ranked.empty:
        st.warning("No candidate data is available. Please check the project data files.")
        return
    names = ranked["site"].tolist()
    if st.session_state.selected_site not in names:
        st.session_state.selected_site = names[0]
    st.session_state.site_choice = st.session_state.selected_site
    passing = int(ranked["passes"].sum())
    if not passing:
        st.warning("No candidate passes all selected limits for this mission. "
                   "Inspect the reasons, adjust your limits, or explore another date. " + ESTIMATE)
    else:
        st.markdown(f"**{passing} of {len(ranked)} candidates pass** · NASA-anchored estimate")
    map_col, detail_col = st.columns([1.65, 1], gap="large")
    with detail_col:
        st.selectbox("Inspect a candidate", names, key="site_choice", on_change=select_site)
        row = next(r for r in ranked.itertuples() if r.site == st.session_state.selected_site)
        site_details(row)
    with map_col:
        st.markdown('<div class="eyebrow">South polar stereographic / top-down</div>', unsafe_allow_html=True)
        st.plotly_chart(make_map(ranked, row.site), use_container_width=True, theme=None, key="site_map",
                        on_select=select_map_site, selection_mode="points",
                        config={"displayModeBar": False, "scrollZoom": False})
        st.markdown('<div class="legend"><span><b style="color:#76c5b0">●</b>Passes</span>'
                    '<span><b style="color:#748296">●</b>Below a limit</span>'
                    '<span><b style="color:#edbd75">○</b>Selected</span></div>', unsafe_allow_html=True)
        st.caption("Click a point or use the selector. Numbers are planner list positions, including failed sites. "
                   "Rings: 50, 100 and 150 projected km; not a terrain basemap. "
                   "0° longitude is +y, 90°E is +x. Drag to pan; double-click to reset.")
    st.divider()
    conditions_panel(row)
    sky_panel(row, landing, days)
    with st.expander("All candidates & ranking method"):
        st.caption(ESTIMATE + " The provisional score is an equal average of the two mission-window "
                   "and two long-term ratios. Failed candidates follow those that pass.")
        fields = ["rank", "site", "sun_window", "earth_window", "sun_long_term", "earth_long_term", "score", "passes", "fail_reasons"]
        st.dataframe(ranked[fields], hide_index=True, use_container_width=True, column_config={
            "rank": "List position", "site": "Candidate", "passes": "Passes limits", "fail_reasons": "Reasons",
            "score": st.column_config.NumberColumn("Provisional score", format="%.3f"),
            **{key: st.column_config.NumberColumn(label, format="%.3f") for key, label in [
                ("sun_window", "Window sunlight (0–1)"), ("earth_window", "Window Earth contact (0–1)"),
                ("sun_long_term", "Long-term sunlight (0–1)"), ("earth_long_term", "Long-term Earth (0–1)")]},
        })
    scan_panel(days)
    with st.expander("Data, assumptions & remaining coverage"):
        st.write(ESTIMATE + " The terrain skyline comes from NASA LOLA elevation models, viewed from "
                 "2 m above the surface. A constant per site and body shifts the skyline to match NASA's "
                 "18.6-year long-term visibility. Near the pole, small terrain changes affect individual dates.")
        st.write("Earth visible means any part of Earth's disc clears its calibrated skyline. "
                 "A particular ground station may still be out of view.")
        st.write("Sun and Earth positions were checked against NASA JPL Horizons and agree within 0.01°, "
                 "according to the team's validation. All 13 Artemis III regions are included.")
        st.write("**Slope:** not available yet  \n**Custom coordinates:** not available yet")
        st.caption("NASA LOLA supplies the long-term averages and terrain. This interface uses the project's "
                   "provided data and does not independently revalidate the scientific model.")


def main():
    st.set_page_config(page_title="Lunar / Landing — Mission Planner", page_icon="◒", layout="wide")
    init_state()
    shell()
    if st.session_state.step == 1:
        date_page()
    else:
        sites_page()
    st.markdown('<div class="footer">Lunar Landing Optimal System · NASA Space Apps Challenge 2026 project'
                ' &nbsp; / &nbsp; Interface generated with OpenAI Codex.</div>', unsafe_allow_html=True)


if __name__ == "__main__":
    main()
